// /schema.json: Facet's one schema surface (renderer/catalogue/schema.json, generated by renderer/tools/gen_catalogue.mjs:
// tokens, components, screens, feeds, settings, themes, the panel's HTTP routes), as a panel serves it at GET /fw/schema.
import type { APIRoute } from 'astro';
import schema from '../../../renderer/catalogue/schema.json';

export const GET: APIRoute = () => new Response(JSON.stringify(schema), { headers: { 'Content-Type': 'application/json' } });
